import test from 'node:test';
import assert from 'node:assert/strict';
import {buildBellrunCourse,startBellrun,stepBellrun,toggleMossback,careForMossback,trailState,validateTrailLife,installTrailLife} from '../reconciled-travel.js';
function world(){const scene={location:1,key:'field',theme:0,width:24,height:20,floor:Array.from({length:20},(_,y)=>y===0||y===19?'#'.repeat(24):'#'+'.'.repeat(22)+'#'),objects:[],doors:[],arrive:[3,3]};return {scene,scenes:new Map([[1,scene]]),state:{scene:1,mode:'field',x:3.5,y:3.5,gold:30,chapter:1},walkable(x,y){return this.scene.floor[Math.floor(y)]?.[Math.floor(x)]==='.';},objects(){return [];},interact(){},restore(s){this.state=structuredClone(s);},loadScene(id){this.scene=this.scenes.get(id);this.state.scene=id;}};}
function finish(w){let result;for(let i=0;i<4;i++){const r=w.state.trailLife.relay;[w.state.x,w.state.y]=r.gates[r.index];result=stepBellrun(w,.05);}return result;}
test('Bellrun gates stay on reachable cells and do not mutate the authored map',()=>{const w=world(),old=JSON.stringify(w.scene);const r=buildBellrunCourse(w);assert.equal(r.gates.length,4);for(const [x,y]of r.gates)assert.ok(w.walkable(x,y));assert.ok(r.length>12);assert.equal(JSON.stringify(w.scene),old);});
test('Bellrun refuses cramped interiors and disconnected courses',()=>{const w=world();w.scene.interior='home';assert.throws(()=>buildBellrunCourse(w),/outdoor/);delete w.scene.interior;w.scene.floor=['####','....','####'];w.state.x=1.5;w.state.y=1.5;assert.throws(()=>buildBellrunCourse(w),/space/);});
test('relay rewards and mount bond are awarded only once per actual circuit',()=>{const w=world();startBellrun(w);const gold=w.state.gold;assert.equal(finish(w).first,true);assert.ok(w.state.gold>gold);assert.equal(trailState(w.state).bonded,true);const after=w.state.gold;startBellrun(w);assert.equal(finish(w).first,false);assert.equal(w.state.gold,after);assert.equal(Object.values(w.state.trailLife.records)[0].finishes,2);});
test('crossing the wrong gate never advances a race and paused encounters do not advance time',()=>{const w=world(),r=startBellrun(w);[w.state.x,w.state.y]=r.gates[2];assert.equal(stepBellrun(w,.05),null);assert.equal(r.index,0);const time=r.elapsed;w.state.mode='battle';stepBellrun(w,.1);assert.equal(r.elapsed,time);});
test('relay progress survives serialization without replaying rewards',()=>{const w=world(),r=startBellrun(w);[w.state.x,w.state.y]=r.gates[0];stepBellrun(w,.05);const saved=JSON.parse(JSON.stringify(w.state));assert.equal(validateTrailLife(saved),true);const v=world();installTrailLife(v);v.restore(saved);assert.equal(v.state.trailLife.relay.index,1);const before=v.state.gold;for(let i=1;i<4;i++){const race=v.state.trailLife.relay;[v.state.x,v.state.y]=race.gates[race.index];stepBellrun(v,.05);}assert.ok(v.state.gold>before);assert.equal(v.state.trailLife.rewards.length,1);});
test('corrupt relay save is rejected before replacing the live journey',()=>{const w=world();installTrailLife(w);const before=w.state;const saved=JSON.parse(JSON.stringify(w.state));saved.trailLife.relay={scene:1,gates:[[NaN,2]],index:99};assert.throws(()=>w.restore(saved),/Bellrun/);assert.equal(w.state,before);});
test('Mossback care spends real currency and riding is bounded to outdoor field play',()=>{const w=world();assert.throws(()=>toggleMossback(w),/befriend/);careForMossback(w);assert.equal(w.state.gold,10);assert.equal(toggleMossback(w),true);assert.equal(toggleMossback(w),false);w.state.mode='battle';assert.throws(()=>toggleMossback(w),/outdoor/);assert.throws(()=>careForMossback(w),/20 credits/);});
test('entering an interior dismounts and cancels a race without moving map coordinates',()=>{const w=world();installTrailLife(w);const t=trailState(w.state);t.bonded=true;t.mounted=true;const room={...w.scene,location:2,interior:'home'};w.scenes.set(2,room);w.loadScene(2);assert.equal(t.mounted,false);assert.equal(w.state.x,3.5);assert.equal(w.trailLife.mounted,false);});
test('old saves acquire optional trail state and service hooks leave existing objects intact',()=>{const w=world(),api=installTrailLife(w);const service=api.service;assert.ok(service?.trailService);assert.ok(w.objects().includes(service));assert.equal(installTrailLife(w),api);const old={scene:1,mode:'field',x:3.5,y:3.5,gold:7,chapter:1};w.restore(old);assert.equal(w.state.gold,7);assert.equal(w.state.trailLife.bonded,false);});
